<template><div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16" /><el-form :inline="true"><el-form-item :label="bilingual('客户','Client')"><el-select v-model="query.client" clearable filterable remote :remote-method="q=>lookup('clients',q)" style="width:260px"><el-option v-for="item in options.clients||[]" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" :loading="loading" @click="search">{{bilingual('搜索','Search')}}</el-button><el-button v-if="canEdit" icon="Plus" :disabled="blocked" @click="openCharge">{{bilingual('手工费用','Manual charge')}}</el-button><el-button v-if="canEdit&&kind==='charges'" :disabled="blocked||!selected.length" @click="draft">{{bilingual('所选费用生成账单','Draft invoice from selection')}}</el-button></el-form-item></el-form><el-radio-group v-model="kind" class="mb16"><el-radio-button value="charges">{{bilingual('费用','Charges')}}</el-radio-button><el-radio-button value="invoices">{{bilingual('账单','Invoices')}}</el-radio-button></el-radio-group>
<el-table ref="tableRef" :data="rows" v-loading="loading" border row-key="id" @selection-change="value=>selected=value"><el-table-column v-if="kind==='charges'&&canEdit" type="selection" width="45" :selectable="row=>row.status==='UNCONFIRMED'&&!blocked" /><el-table-column :label="bilingual('客户','Client')" min-width="150"><template #default="scope">{{related('clients',scope.row.client)}}</template></el-table-column><el-table-column :prop="kind==='charges'?'description':'reference'" :label="kind==='charges'?bilingual('描述','Description'):bilingual('账单号','Invoice reference')" min-width="240" show-overflow-tooltip /><el-table-column prop="type" :label="bilingual('类型','Type')" min-width="110" v-if="kind==='charges'" /><el-table-column :label="bilingual('状态','Status')" width="150"><template #default="scope">{{statusLabel(scope.row.status)}}</template></el-table-column><el-table-column :label="kind==='charges'?bilingual('原税前金额','Original net'):bilingual('含税金额','Total')" width="140"><template #default="s">{{moneyText(s.row.amount)}}</template></el-table-column><el-table-column v-if="kind==='charges'" :label="bilingual('调整后税前金额','Adjusted net')" width="160"><template #default="s">{{moneyText(s.row.adjustedAmount??s.row.amount)}}</template></el-table-column><el-table-column prop="currency" :label="bilingual('币种','Currency')" width="100" /><el-table-column :label="bilingual('操作','Actions')" width="120" fixed="right"><template #default="scope"><el-button v-if="kind==='invoices'" link type="primary" :disabled="blocked" @click="openInvoice(scope.row.id)">{{bilingual('查看','View')}}</el-button><el-button v-else-if="canEdit" link type="primary" :disabled="blocked" @click="reviewCharge(scope.row.id)">{{bilingual('申请调整','Adjust charge')}}</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
<el-drawer v-model="chargeOpened" :title="bilingual('手工记录费用','Record a manual charge')" size="min(650px,100%)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><el-alert :title="bilingual('费用提交后不可直接编辑或删除。币种必须与客户一致，税额由账单生成时的规则计算。','Posted charges cannot be directly edited or deleted. Currency follows the client; invoice tax is calculated by the server.')" type="info" :closable="false" class="mb16" /><el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" /><el-form ref="formRef" :model="form" label-position="top" :disabled="blocked"><el-form-item :label="bilingual('客户','Client')" prop="client" :rules="rules"><el-select v-model="form.client" filterable remote :remote-method="q=>lookup('clients',q)" style="width:100%"><el-option v-for="item in options.clients||[]" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item><el-form-item :label="bilingual('仓库（选填）','Warehouse (optional)')"><el-select v-model="form.warehouse" clearable filterable remote :remote-method="q=>lookup('warehouses',q)" style="width:100%"><el-option v-for="item in options.warehouses||[]" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item><el-form-item :label="bilingual('费用描述','Description')" prop="description" :rules="rules"><el-input v-model="form.description" maxlength="500" /></el-form-item><el-form-item :label="bilingual('费用类型','Charge type')"><el-select v-model="form.type"><el-option v-for="item in chargeTypes" :key="item" :label="financeOption(item)" :value="item" /></el-select></el-form-item><el-form-item v-if="Number(user.id)===1" :label="bilingual('账单项目类型（选填）','Invoice item type (optional)')"><el-select v-model="form.invoiceType" clearable filterable style="width:100%"><el-option v-for="item in invoiceTypes" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item :label="bilingual('金额','Amount')" prop="amount" :rules="rules"><el-input v-model="form.amount" inputmode="decimal" maxlength="28" /></el-form-item><el-form-item :label="bilingual('币种（留空使用客户设置）','Currency (empty uses client setting)')"><el-select v-model="form.currency" clearable><el-option v-for="item in ['GBP','USD','EUR','CNY']" :key="item" :label="item" :value="item" /></el-select></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="chargeOpened=false">{{bilingual('关闭','Close')}}</el-button><el-button type="primary" :loading="saving" :disabled="blocked" @click="saveCharge">{{bilingual('提交费用','Post charge')}}</el-button></template></el-drawer>
<el-drawer v-model="invoiceOpened" :title="bilingual('账单详情','Invoice details')" size="min(800px,100%)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><template v-if="invoice"><el-alert v-if="invoiceError" :title="invoiceError" type="error" :closable="false" class="mb16" /><el-descriptions :column="2" border><el-descriptions-item :label="bilingual('账单号','Reference')">{{invoice.reference}}</el-descriptions-item><el-descriptions-item :label="bilingual('状态','Status')">{{statusLabel(invoice.status)}}</el-descriptions-item><el-descriptions-item :label="bilingual('客户','Client')">{{related('clients',invoice.client)}}</el-descriptions-item><el-descriptions-item :label="bilingual('币种','Currency')">{{invoice.currency}}</el-descriptions-item><el-descriptions-item :label="bilingual('税前金额','Net')">{{invoice.net}}</el-descriptions-item><el-descriptions-item :label="bilingual('税额','Tax')">{{invoice.tax}}</el-descriptions-item><el-descriptions-item :label="bilingual('含税金额','Total')">{{invoice.amount}}</el-descriptions-item><el-descriptions-item :label="bilingual('备注','Notes')">{{invoice.notes||'—'}}</el-descriptions-item></el-descriptions><el-table :data="invoice.lines||[]" border class="lines"><el-table-column prop="description" :label="bilingual('项目','Description')" min-width="230" /><el-table-column prop="amount" :label="bilingual('金额','Amount')" width="120" /><el-table-column prop="vatRate" :label="bilingual('税率（%）','VAT (%)')" width="120" /><el-table-column prop="tax" :label="bilingual('税额','Tax')" width="120" /><el-table-column v-if="canEdit&&['DRAFT','CONFIRMED'].includes(invoice.status)" :label="bilingual('操作','Actions')" width="130" fixed="right"><template #default="s"><el-button link type="primary" :disabled="blocked" @click="reviewCharge(s.row.id)">{{bilingual('申请调整','Adjust charge')}}</el-button></template></el-table-column></el-table></template><template #footer><el-button :disabled="saving" @click="invoiceOpened=false">{{bilingual('关闭','Close')}}</el-button><el-button v-if="canEdit&&invoice?.status==='DRAFT'" type="primary" :disabled="blocked" @click="invoiceAction('confirm')">{{bilingual('确认账单','Confirm invoice')}}</el-button><el-button v-if="canEdit&&['DRAFT','CONFIRMED'].includes(invoice?.status)" type="danger" plain :disabled="blocked" @click="invoiceAction('unconfirm')">{{bilingual('撤销账单并释放费用','Unconfirm and release charges')}}</el-button></template></el-drawer></div></template>
<script setup>
import {computed,reactive,ref,watch,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import auth from '@/plugins/auth'
import useUserStore from '@/store/modules/user'
import {getWarehouseLookups} from '@/api/warehouse'
import {moneyText} from '@/warehouse/adjustments'
import {bilingual,financeOption} from '@/warehouse/i18n'
import {financePending,financePendingError,financeBusy,financeRevision,submitFinance,decimalInput} from '@/warehouse/finance'
const emit=defineEmits(['review-charge'])
function reviewCharge(id){invoiceOpened.value=false;emit('review-charge',id)}
const user=useUserStore(),canEdit=computed(()=>auth.hasPermi('warehouse:finance:edit')),kind=ref('charges'),query=reactive({pageNum:1,pageSize:20,client:''}),rows=ref([]),total=ref(0),selected=ref([]),tableRef=ref(),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),invoiceError=ref(''),chargeOpened=ref(false),invoiceOpened=ref(false),invoice=ref(null),form=ref({}),formRef=ref(),options=reactive({}),invoiceTypes=ref([]),blocked=computed(()=>saving.value||financeBusy.value||!!financePending.value||!!financePendingError.value)
const chargeTypes=['Additional','Picking','Storage','Goods In','Collection','Rework'],rules=[{required:true,message:bilingual('请填写此项','Complete this field'),trigger:['blur','change']}],related=(source,id)=>options[source]?.find(item=>item.id===id)?.label||id||'—',statusLabel=value=>bilingual(({UNCONFIRMED:'未确认',INVOICED:'已生成账单',DRAFT:'草稿',CONFIRMED:'已确认',SUPERSEDED:'已重开'})[value]||value,({UNCONFIRMED:'Unconfirmed',INVOICED:'Invoiced',DRAFT:'Draft',CONFIRMED:'Confirmed',SUPERSEDED:'Superseded'})[value]||value)
const tickets=new Map();let generation=0
async function lookup(source,q=''){const ticket=(tickets.get(source)||0)+1;tickets.set(source,ticket);try{const result=await getWarehouseLookups(source,q);if(tickets.get(source)===ticket)options[source]=result.data}catch(e){error.value=e.message}}
async function load(){const ticket=++generation;loading.value=true;error.value='';selected.value=[];try{const result=await request({url:'/warehouse/finance/'+kind.value,method:'get',params:{...query}});if(ticket===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)loading.value=false}}
function search(){query.pageNum=1;load()}
async function openCharge(){if(blocked.value||!canEdit.value)return;form.value={client:query.client,warehouse:'',description:'',type:'Additional',amount:0,currency:'',invoiceType:''};formError.value='';chargeOpened.value=true;if(Number(user.id)===1)try{invoiceTypes.value=(await request({url:'/warehouse/finance/rules/invoiceTypes',method:'get',params:{pageNum:1,pageSize:200}})).rows.filter(item=>item.active)}catch(e){formError.value=e.message}}
async function saveCharge(){if(blocked.value||!canEdit.value)return;saving.value=true;formError.value='';try{if(!await formRef.value.validate().catch(()=>false))return;const payload={requestId:crypto.randomUUID(),client:form.value.client,description:form.value.description,type:form.value.type,amount:decimalInput(form.value.amount,2)};for(const key of ['warehouse','currency','invoiceType'])if(form.value[key])payload[key]=form.value[key];try{await ElMessageBox.confirm(bilingual('确认记录此费用？提交后不可直接编辑或删除。','Post this charge? It cannot be directly edited or deleted afterwards.'),bilingual('提交费用','Post charge'),{type:'warning',confirmButtonText:bilingual('提交','Post'),cancelButtonText:bilingual('取消','Cancel')})}catch{return}await submitFinance({label:bilingual('手工费用','Manual charge'),url:'/warehouse/finance/charges',method:'post',data:payload});chargeOpened.value=false;ElMessage.success(bilingual('费用已记录','Charge posted'))}catch(e){formError.value=e.message==='invalid_decimal'?bilingual('金额须为非负数，最多两位小数。','Enter a non-negative amount with at most two decimal places.'):e.message}finally{saving.value=false}}
async function draft(){if(blocked.value||!canEdit.value||!selected.value.length)return;const chosen=selected.value.map(row=>({id:row.id,client:row.client,status:row.status})),client=chosen[0].client;if(chosen.length>500||chosen.some(row=>row.client!==client||row.status!=='UNCONFIRMED')){error.value=bilingual('请选择同一客户的1至500笔未确认费用。','Select 1–500 unconfirmed charges for one client.');return}saving.value=true;error.value='';try{let name;try{const result=await ElMessageBox.prompt(bilingual('为所选费用生成账单草稿。可填写账单名称。','Create an invoice draft from the selected charges. An invoice name is optional.'),bilingual('生成账单','Draft invoice'),{confirmButtonText:bilingual('生成草稿','Create draft'),cancelButtonText:bilingual('取消','Cancel')});name=result.value||''}catch{return}const result=await submitFinance({label:bilingual('生成账单','Draft invoice'),url:'/warehouse/finance/invoices',method:'post',data:{requestId:crypto.randomUUID(),client,chargeIds:chosen.map(row=>row.id),name}});invoice.value=result.data;invoiceError.value='';invoiceOpened.value=true;ElMessage.success(bilingual('账单草稿已生成','Invoice draft created'))}catch(e){error.value=e.message}finally{saving.value=false}}
async function openInvoice(id){if(blocked.value)return;try{invoice.value=(await request({url:'/warehouse/finance/invoices/'+encodeURIComponent(id),method:'get'})).data;invoiceError.value='';invoiceOpened.value=true}catch(e){error.value=e.message}}
async function invoiceAction(action){if(blocked.value||!canEdit.value||!invoice.value)return;const id=invoice.value.id,version=invoice.value._version;saving.value=true;invoiceError.value='';try{if(!Number.isInteger(version))throw Error(bilingual('缺少账单版本，请重新读取','Invoice version missing. Reopen it.'));try{await ElMessageBox.confirm(action==='confirm'?bilingual('确认这张账单？','Confirm this invoice?'):bilingual('撤销账单并释放原费用，使其可以重新开票？','Unconfirm this invoice and release its original charges for invoicing again?'),bilingual('确认操作','Confirm operation'),{type:'warning',confirmButtonText:bilingual('确认','Confirm'),cancelButtonText:bilingual('取消','Cancel')})}catch{return}const result=await submitFinance({label:action==='confirm'?bilingual('确认账单','Confirm invoice'):bilingual('撤销账单','Unconfirm invoice'),url:'/warehouse/finance/invoices/'+encodeURIComponent(id)+'/actions',method:'post',data:{requestId:crypto.randomUUID(),action,_version:version}});invoice.value=result.data;ElMessage.success(bilingual('账单已更新','Invoice updated'))}catch(e){invoiceError.value=e.message}finally{saving.value=false}}
watch(kind,()=>{query.pageNum=1;load()});watch(financeRevision,()=>{chargeOpened.value=false;load()});onMounted(()=>{load();lookup('clients');lookup('warehouses')})
</script>
<style scoped>.mb16{margin-bottom:16px}.lines{margin-top:20px}</style>


